const resourceGuidance={
coursePack:['Construye un proyecto anual completo mediante hitos. Primero presenta un mapa en tabla con secuencias, periodos, aprendizajes, productos, criterios y sesiones, comprueba la cobertura temporal y curricular y espera aprobación. Después crea una secuencia piloto completa y espera una revisión conjunta antes de producir el resto por bloques. La entrega final debe organizar programación, guías docentes, materiales del alumnado, apoyos de acceso, instrumentos de evaluación, soluciones, fuentes e inventario de archivos en carpetas claramente identificadas. No afirmes que un archivo existe si no lo has creado y comprobado.','Build a complete annual project through approval gates. First present a table mapping sequences, periods, learning, products, criteria and sessions, check time and curriculum coverage and wait for approval. Then create one complete pilot sequence and wait for joint review before producing the rest in batches. The final delivery must organise the programme, teacher guides, learner materials, access supports, assessment tools, answers, sources and file inventory in clearly identified folders. Never claim that a file exists unless it has been created and checked.'],
annual:['Antes de desarrollar el curso completo, presenta un mapa en tabla con unidades, periodos, saberes, reto, producto y sesiones, y espera su aprobación. Comprueba cobertura temporal y curricular.','Before drafting the full course, present a table mapping units, periods, content, challenge, product and sessions, and wait for approval. Check time and curriculum coverage.'],
situation:['Construye una secuencia sostenida por un reto auténtico y una necesidad realista. Define el producto final, su destinatario y para qué será útil. Selecciona normalmente entre 3 y 6 criterios realmente evaluables, sin añadir otros por simple relación temática. Distribuye todas las sesiones con tiempos viables e incluye activación inicial, modelado o andamiaje, aplicación, evidencia individual, retroalimentación, revisión y presentación o uso del producto. Añade una tabla criterio–actividad–evidencia–instrumento e indica en qué sesión se recoge cada evidencia. Separa en otra tabla los saberes vinculados oficialmente a cada criterio que realmente se utilizan y los saberes añadidos solo como propuesta didáctica; no presentes una relación como oficial si no aparece de forma explícita en la fuente. Si acortas la redacción de un saber, encabeza esa columna exactamente «Resumen didáctico del saber — no es redacción oficial»; no sitúes una paráfrasis bajo un encabezado que pueda interpretarse como cita oficial. Si incluyes una ruta esencial por falta de tiempo, debe reducir realmente la duración, enumerar todas las sesiones resultantes, indicar qué sesiones o fases originales se fusionan, distribuir el tiempo de cada sesión fusionada y comprobar que elaboración, revisión, presentación y evidencias imprescindibles caben. Comprueba que los datos del reto permiten realizar todos los cálculos y productos que exiges: añade datos simulados claramente identificados o elimina requisitos incoherentes. Verifica además que cada operación, número y resultado sea adecuado al curso y a los conocimientos previos declarados; no introduzcas decimales, divisiones u otros procedimientos no enseñados solo para sostener el contexto. Cuando sea posible, reformula con una operación equivalente apropiada al nivel, por ejemplo comparando el coste total con un límite total. Evita procedimientos artificialmente largos, como desarrollar una suma repetida extensa, cuando una representación por grupos, cuadrícula o descomposición sea más adecuada.','Build a sequence driven by an authentic challenge and a realistic need. Define the final product, its audience and intended use. Normally select 3–6 criteria that can genuinely be assessed; do not add others merely because they are thematically related. Allocate every session with feasible timings and include initial activation, modelling or scaffolding, application, individual evidence, feedback, revision and presentation or use of the product. Add a criterion–activity–evidence–instrument table and state in which session each piece of evidence is collected. In a separate table, distinguish the officially linked knowledge actually used for each criterion from knowledge added only as an educational proposal; never describe a link as official unless it is explicit in the source. If you shorten the wording of any knowledge item, title that column exactly “Educational summary of the knowledge — not official wording”; do not place a paraphrase under a heading that could be read as an official quotation. If you include an essential route for lost time, it must genuinely reduce the duration, list every resulting session, state which original sessions or phases are merged, allocate the time of every merged session and check that production, review, presentation and indispensable evidence fit. Check that the challenge data support every calculation and product requirement: add clearly labelled simulated data or remove inconsistent requirements. Also verify that every operation, number and result is suitable for the year level and the stated prior learning; do not introduce decimals, division or other untaught procedures merely to sustain the context. Where possible, reframe the task with an equivalent age-appropriate operation, for example comparing a total cost with a total limit. Avoid artificially long procedures, such as writing out an extensive repeated addition, when grouping, arrays or decomposition would be more suitable.'],
unit:['Incluye propósito, secuencia de sesiones, explicación docente, práctica guiada, aplicación, evaluación, recuperación y materiales necesarios.','Include purpose, session sequence, teacher explanation, guided practice, application, assessment, recovery and required materials.'],
session:['Distribuye el tiempo de forma realista e indica qué hace el docente, qué hace el alumnado, qué se observa y qué debe quedar preparado.','Allocate time realistically and state what the teacher does, what learners do, what is observed and what must be prepared.'],
project:['Haz que la pregunta guía sostenga todas las fases. Define hitos, responsabilidades reales, producto público o auténtico y evidencias individuales dentro del trabajo cooperativo.','Make the driving question sustain every phase. Define milestones, real responsibilities, an authentic product and individual evidence within collaborative work.'],
worksheet:['Entrega contenido listo para copiar a un documento, con consignas claras, espacio de respuesta proporcional, progresión de dificultad y soluciones separadas. Antes de finalizar, comprueba que cada pregunta y cada solución puedan justificarse únicamente con el material que verá el alumnado, no con fragmentos retirados durante la adaptación ni con supuestos del solucionario. Conserva cualquier fragmento imprescindible o reformula la pregunta. Revisa con precisión las secuencias y comparaciones numéricas, distinguiendo aumento, descenso y estabilidad. Agrupa las actividades por la acción observable que exigen y asigna a cada bloque el criterio que realmente demuestra; no uses un único criterio como paraguas para tareas que evidencian acciones diferentes.','Deliver content ready to place in a document, with clear instructions, proportionate answer space, difficulty progression and separate solutions. Before finishing, check that every question and answer can be justified solely from the material learners will actually see, not from passages removed during adaptation or assumptions introduced in the answer key. Preserve any indispensable passage or rewrite the question. Review numerical sequences and comparisons precisely, distinguishing increase, decrease and stability. Group activities by the observable action they require and assign each block to the criterion it genuinely demonstrates; do not use one criterion as an umbrella for tasks evidencing different actions.'],
presentation:['Organiza una narrativa breve por diapositivas, con una idea principal por pantalla, participación frecuente y notas útiles para quien presenta.','Organise a concise slide narrative with one main idea per screen, frequent participation and useful presenter notes.'],
visual:['Prioriza jerarquía, lectura rápida, pocas palabras y relaciones visuales explícitas. Incluye el texto exacto y una descripción de composición accesible.','Prioritise hierarchy, quick scanning, few words and explicit visual relationships. Include exact copy and an accessible layout description.'],
listening:['Genera un guion oral natural ajustado al nivel, objetivo antes de escuchar, tareas de preescucha, escucha global y detallada, transcripción, soluciones, apoyos y pauta de locución.','Create a natural spoken script for the level, a pre-listening purpose, gist and detail tasks, transcript, answers, scaffolds and voice directions.'],
comic:['Entrega sinopsis, personajes, guion por viñetas, diálogos breves, descripción visual consistente, texto alternativo y un prompt reutilizable en la herramienta elegida.','Deliver a synopsis, characters, panel-by-panel script, concise dialogue, consistent visual descriptions, alt text and a reusable prompt for the chosen tool.'],
image:['Especifica función didáctica, composición, elementos obligatorios y prohibidos, estilo, formato, texto visible exacto, texto alternativo y un prompt final para un generador de imágenes.','Specify teaching purpose, composition, required and forbidden elements, style, format, exact visible text, alt text and a final image-generation prompt.'],
video:['Entrega objetivo, duración, guion de voz, storyboard por escenas con tiempos, recursos visuales, rótulos, subtítulos, accesibilidad y plan de edición en la herramienta elegida.','Deliver the objective, length, voice-over, timed scene storyboard, visual assets, captions, subtitles, accessibility and an editing plan for the chosen tool.'],
interactive:['Define mecánica, objetivo de aprendizaje, reglas, estados de acierto y error, retroalimentación explicativa, accesibilidad y criterio de finalización.','Define mechanics, learning goal, rules, success and error states, explanatory feedback, accessibility and completion criteria.'],
curriculumMap:['Recopila TODAS las competencias específicas y TODOS los criterios de evaluación de la materia y nivel indicados desde el anexo oficial exacto. Conserva sus códigos, resume cada elemento con claridad sin alterar su sentido y señala cualquier elemento no localizado. No selecciones una muestra. Añade una idea breve y viable de actividad o evidencia por criterio solo si se solicita, diferenciándola del texto oficial.','Compile ALL specific competencies and ALL assessment criteria for the stated subject and level from the exact official annex. Preserve their codes, summarise each item clearly without changing its meaning and flag anything not found. Do not provide a sample. Add one brief feasible assessment activity or evidence per criterion only if requested, clearly separating it from official wording.'],
rubric:['Usa criterios observables, descriptores positivos y progresivos, el mismo foco en todos los niveles y evidencias que realmente puedan recogerse.','Use observable criteria, positive progressive descriptors, the same focus across levels and evidence that can actually be collected.'],
test:['Incluye tabla de especificaciones, variedad cognitiva, instrucciones, puntuación, soluciones razonadas y errores habituales; evita preguntas ambiguas.','Include a test blueprint, cognitive variety, instructions, scoring, reasoned answers and common misconceptions; avoid ambiguous questions.'],
assessment:['Relaciona cada instrumento con una evidencia y un criterio. Distingue evaluación formativa de calificación y añade autoevaluación cuando tenga sentido.','Link each tool to evidence and a criterion. Distinguish formative assessment from grading and add self-assessment where appropriate.'],
adapt:['Concreta cada apoyo en una actividad y una barrera. Mantén criterios, exigencia cognitiva y producto común, ofreciendo alternativas de acceso y expresión.','Tie each support to an activity and barrier. Maintain common criteria, cognitive demand and product while offering access and expression options.'],
support:['Para refuerzo, vuelve al punto exacto de dificultad con andamiaje; para ampliación, plantea decisiones abiertas, demostración o creación útil, no más cantidad.','For support, return to the exact difficulty with scaffolding; for extension, use open decisions, proof or useful creation, not more quantity.'],
family:['Escribe con lenguaje claro, respetuoso y accionable. Evita jerga, juicios y datos sensibles; diferencia hechos observables, acuerdos y próximos pasos.','Use clear, respectful and actionable language. Avoid jargon, judgement and sensitive data; distinguish observations, agreements and next steps.'],
tutoring:['Incluye un clima seguro, instrucciones concretas, participación no forzada, cierre reflexivo y pautas para responder ante situaciones delicadas.','Include psychological safety, concrete instructions, non-forced participation, reflection and guidance for sensitive situations.'],
feedback:['Separa logros, evidencia concreta, siguiente paso y una oportunidad de mejora o reentrega. No atribuyas intenciones ni uses etiquetas personales.','Separate strengths, concrete evidence, next step and an opportunity to improve or resubmit. Do not attribute intentions or use personal labels.'],
free:['Aclara primero el propósito, destinatario, uso real, restricciones y formato final. Si falta un dato decisivo, pregunta antes de producir el recurso.','Clarify purpose, audience, real use, constraints and final format. Ask before producing the resource if a decisive detail is missing.']
};
const state={step:0,lang:0,category:'all',resource:'',mode:'quick',suggestedMethods:[],suggestedAssessment:[]};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function tr(key){return translations[key]?.[state.lang]||key}
function applyTranslations(){$$('[data-i18n]').forEach(el=>el.textContent=tr(el.dataset.i18n))}
function init(){applyTranslations();renderSteps();renderCategories();renderResources();renderEducation();renderFramework();renderChips();renderSourceChoices();renderStaticSelects();bind();update();updateCurriculumSource();updateSourceFields();document.body.classList.add('quick-mode')}
function renderSteps(){$('#steps').innerHTML=stepNames.map((n,i)=>`<button type="button" class="step-item ${i===state.step?'active':''}" data-go="${i}"><span class="num">${i<state.step?'✓':i+1}</span><span class="label">${n[state.lang]}</span></button>`).join('')}
function renderCategories(){$('#categoryTabs').innerHTML=Object.entries(categories).map(([id,n])=>`<button type="button" role="tab" aria-selected="${state.category===id}" class="${state.category===id?'active':''}" data-cat="${id}">${n[state.lang]}</button>`).join('')}
function renderResources(){const items=resources.filter(r=>state.category==='all'||r.cat===state.category);$('#resourceGrid').innerHTML=items.map(r=>`<button type="button" class="resource-card ${state.resource===r.id?'selected':''}" data-resource="${r.id}" aria-pressed="${state.resource===r.id}"><span class="icon">${r.icon}</span><strong>${state.lang?r.en:r.es}</strong><small>${state.lang?r.descEn:r.descEs}</small></button>`).join('')}
function renderSourceChoices(){const mode=$('#sourceMode'),action=$('#sourceAction'),m=mode.value,a=action.value;const modes=[['free','Crear desde cero, sin adjuntos','Create from scratch, no attachments'],['documents','Basarse en uno o varios documentos','Use one or more documents'],['text','Basarse en un texto que pegaré','Use text I will paste'],['images','Basarse en una o varias imágenes','Use one or more images'],['mixed','Combinar documentos, texto e imágenes','Combine documents, text and images'],['hybrid','Usar mis fuentes y completar con creación propia','Use my sources and add original content']];const actions=[['analyse','Analizar y crear a partir de ellas','Analyse and create from them'],['adapt','Adaptar el contenido al grupo','Adapt the content to the group'],['extract','Extraer y organizar la información','Extract and organise information'],['transform','Transformar el formato conservando el sentido','Change the format while preserving meaning'],['style','Tomarlas como modelo de estilo','Use them as a style reference'],['verify','Contrastar afirmaciones y detectar lagunas','Check claims and identify gaps']];const option=x=>`<option value="${x[0]}" data-es="${x[1]}" data-en="${x[2]}">${x[state.lang+1]}</option>`;mode.innerHTML=modes.map(option).join('');action.innerHTML=actions.map(option).join('');if(m)mode.value=m;if(a)action.value=a}
function renderEducation(){const current=$('#education').value;$('#education').innerHTML='<option value="">'+(state.lang?'Choose…':'Selecciona…')+'</option>'+education.map(e=>`<option value="${e[0]}">${e[state.lang]}</option>`).join('');$('#education').value=current;renderAcademicOptions(true);updateModel()}
function renderAcademicOptions(preserve=false){const stage=$('#education').value,data=academicCatalog[stage],level=$('#level'),subject=$('#subject'),oldLevel=preserve?level.value:'',oldSubject=preserve?subject.value:'',prompt=state.lang?'Select…':'Selecciona…',waiting=state.lang?'Choose an education setting first':'Selecciona primero una enseñanza';if(!data){level.innerHTML=`<option value="">${waiting}</option>`;subject.innerHTML=`<option value="">${waiting}</option>`;level.disabled=true;subject.disabled=true;updateAcademicOther();return}const addOther=rows=>rows.some(x=>x[0]==='__other')?rows:[...rows,['__other','Otro: especificar','Other: specify']],option=x=>`<option value="${x[0]}" data-es="${x[1]}" data-en="${x[2]}">${x[state.lang+1]}</option>`;level.innerHTML=`<option value="">${prompt}</option>`+addOther(data.levels).map(option).join('');subject.innerHTML=`<option value="">${prompt}</option>`+addOther(data.subjects).map(option).join('');level.disabled=false;subject.disabled=false;if([...level.options].some(o=>o.value===oldLevel))level.value=oldLevel;if([...subject.options].some(o=>o.value===oldSubject))subject.value=oldSubject;updateAcademicOther()}
function updateAcademicOther(){const levelOther=$('#levelOther'),subjectOther=$('#subjectOther'),customLevel=$('#level').value==='__other',customSubject=$('#subject').value==='__other',complex=['Formación Profesional','Conservatorio de Música o Danza','Enseñanzas Artísticas Superiores','Universidad'].includes($('#education').value);levelOther.hidden=!customLevel;levelOther.required=customLevel;subjectOther.hidden=!customSubject;subjectOther.required=customSubject;$('#academicDetailWrap').hidden=!complex;$('#academicDetail').required=complex;levelOther.placeholder=state.lang?'Specify the year or level':'Especifica el curso o nivel';subjectOther.placeholder=state.lang?'Specify the area, subject, module or course':'Especifica el área, materia, módulo o asignatura';$('#academicDetail').placeholder=state.lang?'E.g. Web Development VET · Programming':'Ej. CFGS Desarrollo de Aplicaciones Web · Programación'}
