function renderStaticSelects(){Object.entries(staticSelectTranslations).forEach(([name,rows])=>{const el=$(`[name="${name}"]`);if(!el)return;[...el.options].forEach((o,i)=>{if(rows[i]){o.dataset.es=rows[i][0];o.dataset.en=rows[i][1];o.textContent=rows[i][state.lang]}})})}
