$$('.mode-switch button').forEach(b=>b.onclick=()=>{$$('.mode-switch button').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.mode=b.dataset.mode;document.body.classList.toggle('quick-mode',state.mode==='quick')});
