function updateModel(){const e=$('#education').value;let model='Modelo competencial LOMLOE';if(/Profesional/.test(e))model='Modelo de resultados de aprendizaje (FP)';else if(/Universidad|Conservatorio|Artísticas|Idiomas|no reglada|Otra/.test(e))model='Modelo de objetivos y resultados de aprendizaje';else if(/Especial/.test(e))model='Modelo individualizado y competencial';$('#modelText').textContent=state.lang?({'Modelo competencial LOMLOE':'LOMLOE competency-based model','Modelo de resultados de aprendizaje (FP)':'Learning outcomes model (VET)','Modelo de objetivos y resultados de aprendizaje':'Objectives and learning outcomes model','Modelo individualizado y competencial':'Individualised competency-based model'}[model]):model;updateCurriculumSource()}
function curriculumEntry(){return window.ANDALUSIA_CURRICULUM?.stages?.[$('#education').value]||null}
function updateCurriculumSource(){const entry=curriculumEntry();const mode=document.querySelector('[name="curriculumMode"]')?.value||'verified';const title=$('#curriculumSourceTitle'),note=$('#curriculumSourceNote'),status=$('#curriculumStatus'),link=$('#curriculumSourceLink');if(mode==='none'){title.textContent=state.lang?'Curriculum references disabled':'Referencias curriculares desactivadas';note.textContent=state.lang?'The final prompt will focus on learning objectives without citing regulations.':'El prompt final se centrará en objetivos de aprendizaje sin citar normativa.';status.textContent=state.lang?'Not used':'No se usará';link.hidden=true;return}if(mode==='own'){title.textContent=state.lang?'Your own verified references':'Tus propias referencias verificadas';note.textContent=state.lang?'Paste the official curriculum elements in the field below. The AI will use only that information.':'Pega en el campo inferior los elementos curriculares oficiales. La IA utilizará únicamente esa información.';status.textContent=state.lang?'User source':'Fuente propia';link.hidden=true;return}link.hidden=false;if(!entry){title.textContent=state.lang?'Select an education setting':'Selecciona una enseñanza';note.textContent=state.lang?'We will show the available official reference and its coverage here.':'Aquí mostraremos la referencia oficial disponible y su grado de cobertura.';status.textContent=state.lang?'Waiting':'Pendiente';link.href='https://www.juntadeandalucia.es/boja/';return}title.textContent=entry.title;note.textContent=entry.note;status.textContent=(entry.status==='base'?(state.lang?'Official base':'Base oficial'):(state.lang?'Specific source required':'Requiere concreción'))+` · ${window.ANDALUSIA_CURRICULUM.verifiedOn}`;link.href=entry.url}
function setSuggestions(){const id=state.resource;let m=['Práctica guiada','Aprendizaje cooperativo'],a=['Evaluación formativa','Observación sistemática'];if(['situation','project','coursePack'].includes(id)){m=['Aprendizaje basado en retos','Aprendizaje cooperativo'];a=['Rúbrica','Autoevaluación','Producto final']}if(['rubric','test','assessment','curriculumMap'].includes(id)){m=['Práctica guiada'];a=['Evaluación formativa','Autoevaluación','Lista de cotejo']}if(['adapt','support'].includes(id)){m=['Instrucción explícita','Práctica guiada'];a=['Evaluación formativa','Observación sistemática']}if(['interactive','comic','video'].includes(id)){m=['Gamificación','Aprendizaje basado en retos'];a=['Autoevaluación','Observación sistemática']}const sessionDefaults={coursePack:90,annual:90,situation:6,unit:8,session:1,project:8,worksheet:1,presentation:1,visual:1,listening:1,comic:2,image:1,video:3,interactive:1,curriculumMap:1,rubric:1,test:1,assessment:1,adapt:1,support:2,family:1,tutoring:1,feedback:1,free:1};if(id&&document.querySelector('[name="sessions"]'))document.querySelector('[name="sessions"]').value=sessionDefaults[id]||1;const scope=document.querySelector('[name="scope"]');if(scope&&id)scope.value=['annual','coursePack','curriculumMap'].includes(id)?'Alineación curricular completa':'Solo referencias esenciales';state.suggestedMethods=m;state.suggestedAssessment=a;$('#suggestionText').textContent=(state.lang?'Try: ':'Prueba con: ')+[...m,...a].map(term).join(' · ');if(id==='curriculumMap'){$('#sourceMode').value='documents';$('#sourceAction').value='extract';updateSourceFields()}}
