function primaryCurriculumSelection(){
  if($('#education').value!=='Primaria'||!window.PRIMARY_CURRICULUM)return null;
  const grade=$('#level').value,rawSubject=$('#subject').value;
  if(!/^[1-6]$/.test(grade))return null;
  const data=window.PRIMARY_CURRICULUM,subjectId=data.aliases[rawSubject]||rawSubject,subject=data.subjects[subjectId];
  if(!subject)return null;
  const cycle=String(Math.ceil(Number(grade)/2)),cycleData=subject.cycles[cycle];
  if(!cycleData||!cycleData.criteriaByGrade[grade])return null;
  return {data,subject,subjectId,grade,cycle,cycleData,criteria:cycleData.criteriaByGrade[grade]};
}
function infantCurriculumSelection(){
  if($('#education').value!=='Infantil'||!window.INFANT_CURRICULUM)return null;
  const level=$('#level').value,subjectId=$('#subject').value;
  if(!['c1','c2','3','4','5'].includes(level))return null;
  const data=window.INFANT_CURRICULUM,subject=data.subjects[subjectId],cycle=level==='c1'?'1':'2';
  if(!subject)return null;
  const cycleData=subject.cycles[cycle];if(!cycleData)return null;
  return {data,subject,subjectId,level,cycle,cycleData,criteria:cycleData.criteria};
}
function esoCurriculumSelection(){
  if($('#education').value!=='ESO'||!window.ESO_CURRICULUM)return null;
  const level=$('#level').value,requestedSubject=$('#subject').value;
  if(!['1','2','3','4','div1','div2'].includes(level))return null;
  const data=window.ESO_CURRICULUM,subjectId=data.aliases?.[requestedSubject]||requestedSubject,subject=data.subjects[subjectId],grade=level.startsWith('div')?level.slice(3):level;
  if(!subject)return null;
  const isDiversification=level.startsWith('div'),isDomain=['ambito-ling','ambito-cient'].includes(subjectId);
  if(isDiversification!==isDomain)return null;
  const gradeData=subject.grades[grade];if(!gradeData)return null;
  return {data,subject,subjectId,level,grade,gradeData};
}
function bachLevelData(level=$('#level').value){
  if(/^adult[12]$/.test(level))return {grade:level.slice(-1),mode:'adult'};
  const match=level.match(/^([12])-(.+)$/);return match?{grade:match[1],mode:match[2]}:null;
}
function bachCurriculumSelection(){
  if($('#education').value!=='Bachillerato'||!window.BACH_CURRICULUM)return null;
  const level=$('#level').value,levelData=bachLevelData(level),requestedSubject=$('#subject').value;if(!levelData)return null;
  const data=window.BACH_CURRICULUM,subjectId=data.aliases?.[requestedSubject]||requestedSubject,subject=data.subjects[subjectId];
  if(!subject)return null;const gradeData=subject.grades[levelData.grade];if(!gradeData)return null;
  if(!['adult','otra'].includes(levelData.mode)){const allowed=new Set([...bachCommon[levelData.grade],...bachOptional[levelData.grade],...(bachByMode[levelData.mode]?.[levelData.grade]||[])]);if(!allowed.has(subjectId))return null}
  return {data,subject,subjectId,level,grade:levelData.grade,mode:levelData.mode,gradeData};
}
