  if(!active){family.disabled=true;title.disabled=true;return}
  const oldFamily=preserve?family.value:'',oldTitle=preserve?title.value:'',oldSubject=preserve?subject.value:'',info=fpLevelData(),prompt=state.lang?'Select…':'Selecciona…';
  if(!info){family.innerHTML=`<option value="">${state.lang?'Choose the level and year first':'Selecciona primero el grado y curso'}</option>`;title.innerHTML=`<option value="">${state.lang?'Choose a professional family first':'Selecciona primero una familia profesional'}</option>`;subject.innerHTML=`<option value="">${state.lang?'Choose a qualification first':'Selecciona primero un título'}</option>`;family.disabled=true;title.disabled=true;subject.disabled=true;return}
