updateModel=function(){updateModelBeforeFp();adaptFpCurriculumMapCopy()};
$('#education').onchange=()=>{renderAcademicOptions();updateModel()};

/* Beta audit: the reference collection is not the scope of every resource. */
function curriculumExecutionPolicy(v,isEn){
  if(v.resourceId==='curriculumMap'){
    const rules=isEn?[
      'Source provenance: embedded text is a transcription supplied by PromptDocentes, not an attachment. Do not claim to have read documents, opened links or verified legislation unless you actually did so.',
      v.sourceMode==='free'?'Start with “Resource created from the prompt”. No attachments are announced.':'Name only attachments actually accessible and distinguish them from embedded curriculum text.',
      'Cover every competency and assessment criterion in the requested scope. Include exactly one identifiable row/card or outline entry per criterion, grouped by competency, preserving all codes. Compare expected and delivered counts by year/cycle and list missing codes. A concise summary must not omit criteria. If split into parts, report the remaining codes.',
      'Respect the selected table, cards or outline format. Do not add lesson plans, session times, materials, prior knowledge, cooperative roles, standalone UDL sections or an essential route unless explicitly requested in the additional request.',
      'Use three separate final statuses: transcription coverage (counts and missing codes), proposed activity alignment (complete, partial, pending, or not applicable without activities), and normative currency (source edition and unresolved amendment checks). Complete coverage does not establish full assessment or current legislation.',
      'Treat criterion–knowledge links as official only when an explicit source table is supplied or actually consulted; otherwise label them educational proposals. Do not infer links from proximity or similar wording.'
    ]:[
      'Procedencia: el texto incorporado es una transcripción aportada por PromptDocentes, no un adjunto. No afirmes haber leído documentos, abierto enlaces ni verificado normativa si no lo has hecho.',
      v.sourceMode==='free'?'Empieza con «Recurso elaborado a partir del prompt». No se anuncian adjuntos.':'Nombra solo los adjuntos realmente accesibles y distínguelos del texto curricular incorporado.',
      'Abarca todas las competencias y todos los criterios del alcance solicitado. Incluye exactamente una fila, ficha o entrada de esquema identificable por criterio, agrupada por competencia, y conserva todos los códigos. Compara cantidades esperadas y entregadas por curso/ciclo y enumera los códigos pendientes. Un resumen conciso no debe omitir criterios. Si divides la entrega, indica los códigos restantes.',
      'Respeta el formato elegido: tabla, fichas o esquema. No añadas sesiones, tiempos, materiales, conocimientos previos, roles cooperativos, apartados independientes de DUA ni ruta esencial salvo petición expresa en las condiciones adicionales.',
      'Cierra con tres estados separados: cobertura de la transcripción (cantidades y códigos pendientes), alineación de las actividades propuestas (completa, parcial, pendiente o no aplicable si no hay actividades) y vigencia normativa (edición de la fuente y modificaciones pendientes de contrastar). Una cobertura completa no acredita evaluación completa ni normativa vigente.',
      'Una relación criterio–saber solo es oficial si procede de una tabla explícita aportada o realmente consultada; etiqueta las demás como propuestas didácticas. No deduzcas relaciones por proximidad o semejanza.'
    ];
    const wording=v.officialWording||'both';
    rules.push(isEn?
      'Faithful summaries must retain progression and support qualifiers such as beginning to, initiating, guided, and independently, as well as required cooperation, medium and context. Do not replace an introductory or guided expectation with autonomous mastery. Condense wording, not the required actions or conditions.':
      'Los resúmenes fieles deben conservar los matices de progresión y apoyo: comenzar, iniciarse, de forma pautada o autónomamente, así como cooperación, medio y contexto exigidos. No conviertas una expectativa inicial o guiada en dominio autónomo. Acorta la redacción, no las acciones ni las condiciones del criterio.');
    rules.push(isEn?(wording==='official'?'Reproduce only exact official Spanish wording, without educational summaries.':wording==='summary'?'Provide faithful concise summaries labelled “Educational summary — not official wording”; do not duplicate the full official wording.':'Separate exact official Spanish wording from concise summaries labelled “Educational summary — not official wording”.'):(wording==='official'?'Reproduce solo la redacción oficial exacta, sin resúmenes didácticos.':wording==='summary'?'Entrega resúmenes fieles y concisos etiquetados «Resumen didáctico — no es redacción oficial»; no dupliques el texto oficial completo.':'Separa la redacción oficial exacta de los resúmenes concisos etiquetados «Resumen didáctico — no es redacción oficial».'));
    rules.push(v.includeIdeas==='no'?(isEn?'No activity ideas requested: omit activities, evidence, instruments and support columns. Mark activity alignment not applicable.':'No se solicitan ideas: omite actividades, evidencias, instrumentos y columnas de apoyos. Marca la alineación de actividades como no aplicable.'):(isEn?'Suggest one brief feasible activity and observable individual evidence per criterion, clearly labelled as proposals. Check every required action, not just the topic. Comparing strategies requires at least two actual strategies. Handling a tool requires using it to solve the problem, not merely choosing it. Interpreting an everyday mathematical message requires an actual message and its interpretation, not vocabulary alone. Preserve qualifiers about guidance and autonomy; state any partial coverage. Do not claim these proposed activities have already demonstrated learning.':'Sugiere por criterio una actividad breve y viable y una evidencia individual observable, identificadas como propuestas. Comprueba todas las acciones exigidas, no solo el tema. Comparar estrategias exige al menos dos estrategias reales. Manejar una herramienta exige utilizarla para resolver el problema, no solo elegirla. Interpretar un mensaje matemático cotidiano exige un mensaje concreto y su interpretación, no solo vocabulario. Conserva los matices de guía y autonomía; señala cualquier cobertura parcial. No afirmes que las propuestas ya han demostrado aprendizaje.'));
    if(v.includeIdeas!=='no')rules.push(isEn?
      'Audit each proposed activity against every required action, progression/support qualifier, grouping, medium and context in its criterion. If cooperation is required, include actual peer interaction and individual evidence; an individual representation alone is insufficient. If a digital process is required, include a concrete simple digital process; ordering paper cards alone is partial. If equality, respect for diversity or peaceful conflict resolution is required, propose observable behaviours in a relevant interaction, not just roles and listening. Retain introductory/guided expectations. Mark any uncovered demand as partial or pending beside that criterion, naming what is missing. A row, activity title or instrument name is not proof of full alignment. In the final status list affected codes; declare complete design alignment only when every required demand is explicitly covered. These remain untested proposals, not demonstrated pupil learning.':
      'Contrasta cada actividad con todas las acciones, matices de progresión y apoyo, agrupamiento, medio y contexto exigidos por su criterio. Si exige cooperación, concreta interacción entre iguales y evidencia individual; una representación individual no basta. Si exige un proceso digital, incluye un proceso digital sencillo concreto; ordenar tarjetas de papel es parcial. Si exige igualdad, respeto a la diversidad o resolución pacífica de conflictos, propone conductas observables en una interacción pertinente, no solo roles y escucha. Mantén las expectativas iniciales o pautadas. Marca junto al criterio cualquier exigencia no cubierta como parcial o pendiente, indicando qué falta. Tener una fila, un título de actividad o un instrumento no prueba alineación completa. En el cierre enumera los códigos afectados; declara alineación completa del diseño solo si todas las exigencias están cubiertas explícitamente. Siguen siendo propuestas sin probar, no aprendizaje demostrado del alumnado.');
    if(v.curriculumMode==='none')rules.push(isEn?'No official curriculum is requested: do not invent codes or official completeness; report normative coverage as not established.':'No se solicita currículo oficial: no inventes códigos ni exhaustividad oficial; declara la cobertura normativa no establecida.');
    return `\n# ${isEn?'CURRICULUM MAP QUALITY CONTROL':'CONTROL DE CALIDAD DEL MAPA CURRICULAR'}\n${rules.map(rule=>`- ${rule}`).join('\n')}\n`;
  }
  const complete=['annual','coursePack','curriculumMap'].includes(v.resourceId),extended=['situation','unit','project'].includes(v.resourceId);
  const rules=isEn?[
    'Source provenance: material embedded in this prompt is not an attached file. Do not claim to have read documents, opened links or checked current legislation unless you actually did so. Identify embedded wording as a transcription supplied by PromptDocentes.',
    'Keep official Spanish wording, your labelled plain-language summaries and your educational proposals separate. Preserve the exact wording and codes of any element reproduced as official.',
    complete?'Cover every competency and assessment criterion within the requested year/cycle/subject scope. Annual planning must distribute them across the year, not assess everything in every session. Report gaps rather than silently reducing coverage.':extended?'The embedded collection is a reference bank, not the scope of this resource. Select a coherent, limited set that can be taught, practised and evidenced in the sequence—normally 3–6 assessment criteria. Justify each selection through actual activity and evidence; do not add transversal criteria solely because pupils work in groups.':'The embedded collection is a reference bank, not a requirement to teach or assess every item. Select only elements justified by the topic, duration and actual learner evidence. For one short session, normally prioritise 2–4 assessment criteria; do not add transversal criteria solely because pupils work in pairs.',
    'For resources with assessment, include a concise table: selected criterion code | activity | observable individual evidence | instrument. Distinguish supported practice from independently demonstrated learning.',
    'Use the provided core-knowledge descriptions. Treat criterion–knowledge links as official only if an explicit source table is included or actually consulted. Label other links as educational proposals; never infer an official link from proximity or similar wording.',
    'State source edition and unresolved currency checks. A built-in transcription is not proof that later amendments have been integrated. Do not call alignment complete when relevant source content or links are absent.',
    'Identify materials and prior knowledge, give realistic times including transitions, and offer an essential route if time is short. Link each inclusive support to a specific barrier and task. Finish with results of the checks, not an uncompleted checklist.'
  ]:[
    'Procedencia: el texto incorporado en este prompt no es un archivo adjunto. No afirmes haber leído documentos, abierto enlaces ni comprobado la normativa vigente si no lo has hecho. Identifica el bloque como transcripción aportada por PromptDocentes.',
    'Separa redacción oficial, resúmenes en lenguaje claro identificados como tales y propuestas didácticas. Conserva la redacción y los códigos exactos de los elementos que reproduzcas como oficiales.',
    complete?'Abarca todas las competencias y todos los criterios dentro del alcance solicitado de curso/ciclo y materia. En una programación anual distribúyelos durante el curso: no evalúes todos en cada sesión. Señala las ausencias sin reducir silenciosamente la cobertura.':extended?'La colección incorporada es un banco de referencia, no el alcance del recurso. Selecciona un conjunto coherente y limitado que pueda enseñarse, practicarse y evidenciarse en la secuencia: normalmente entre 3 y 6 criterios. Justifica cada selección mediante actividades y evidencias reales; no añadas criterios transversales solo porque se trabaje en grupo.':'La colección incorporada es un banco de referencia, no una obligación de trabajar o evaluar todos sus elementos. Selecciona únicamente los pertinentes al tema, duración y evidencias reales. Para una sesión breve prioriza normalmente 2–4 criterios; no añadas criterios transversales solo porque se trabaje por parejas.',
    'En recursos con evaluación incluye una tabla breve: código del criterio seleccionado | actividad | evidencia individual observable | instrumento. Diferencia la práctica con apoyo del aprendizaje demostrado de forma autónoma.',
    'Utiliza las descripciones de saberes incorporadas. Una relación criterio–saber solo es oficial si está recogida en una tabla explícita aportada o realmente consultada. Identifica las demás relaciones como propuestas didácticas; no deduzcas una vinculación oficial por proximidad o semejanza.',
    'Indica la edición de la fuente y las comprobaciones de vigencia pendientes. Una transcripción incorporada no demuestra que estén integradas las modificaciones posteriores. No declares alineación completa si faltan contenidos o relaciones pertinentes.',
    'Identifica materiales y conocimientos previos, asigna tiempos realistas incluidas las transiciones y ofrece una ruta esencial si falta tiempo. Vincula cada apoyo inclusivo a una barrera y tarea concreta. Cierra con el resultado de las comprobaciones, no con casillas sin completar.'
  ];
  rules.push(...(isEn?[
    v.sourceMode==='free'?'No attachments are announced. Start with “Resource created from the prompt”; do not refer to a supplied file or document.':'Name only attachments actually accessible, and distinguish them from the prompt itself.',
    'Label any shortened competency, criterion or core-knowledge wording “Educational summary — not official wording”, including when displayed beside a code. If official wording is requested, reproduce it separately without shortening it.',
    'Before assigning a criterion, check every action it requires against the task and evidence. If a criterion requires comparing strategies, include an actual comparison of at least two strategies; merely using one strategy is insufficient. If only part of a criterion is practised, state that limitation and do not claim full assessment.',
    'For independent evidence, identify the specific individual task, the point at which modelling or peer assistance stops, the access supports that remain available, and what is recorded. Do not certify independence merely because the pupil completes a worksheet.',
    'If cooperative learning is selected, define useful roles, how and when they rotate, and each pupil’s individual contribution. Working in pairs alone does not establish a cooperative method.',
    'In the final check, justify each positive claim with an activity, section or evidence present in the resource. Mark anything not demonstrated as pending or partial rather than claiming compliance.'
  ]:[
    v.sourceMode==='free'?'No se anuncian adjuntos. Empieza con «Recurso elaborado a partir del prompt»; no menciones un archivo o documento aportado.':'Nombra únicamente los adjuntos realmente accesibles y distínguelos del propio prompt.',
    'Etiqueta cualquier formulación abreviada de competencias, criterios o saberes como «Resumen didáctico — no es redacción oficial», también cuando aparezca junto a un código. Si se pide texto oficial, reprodúcelo aparte sin abreviarlo.',
    'Antes de asignar un criterio, comprueba todas las acciones que exige frente a la tarea y evidencia. Si exige comparar estrategias, incluye una comparación real de al menos dos; utilizar una sola no basta. Si solo se practica parte del criterio, declara esa limitación y no afirmes evaluarlo completamente.',
    'Para recoger evidencia autónoma, identifica la tarea individual concreta, cuándo termina el modelado o la ayuda de compañeros, qué apoyos de acceso se mantienen y qué se registra. Completar una ficha no demuestra por sí solo autonomía.',
    'Si se selecciona aprendizaje cooperativo, define roles útiles, cómo y cuándo se intercambian y la aportación individual de cada participante. Trabajar por parejas no acredita por sí solo esa metodología.',
    'En la comprobación final justifica cada afirmación positiva con una actividad, apartado o evidencia presente en el recurso. Marca como pendiente o parcial lo no demostrado, en lugar de declarar cumplimiento.'
  ]));
  if(v.resourceId==='curriculumMap')rules.push(isEn?
    'Map acceptance check: include exactly one identifiable row/card per supplied assessment criterion and preserve every code. Group rows by competency; separate official wording (if requested), educational summary and optional suggested assessment evidence. Check expected counts against delivered counts for each year/cycle. A short summary must not reduce the number of criteria. If length limits require parts, label each part and report the remaining codes; never present a partial map as complete.':
    'Control de aceptación del mapa: incluye exactamente una fila o ficha identificable por criterio aportado y conserva todos los códigos. Agrupa por competencia; separa redacción oficial (si se solicita), resumen didáctico y evidencia de evaluación opcional. Compara el número esperado con el entregado por curso/ciclo. Resumir no significa reducir el número de criterios. Si el límite de respuesta obliga a dividirlo, identifica las partes y los códigos pendientes; no presentes un mapa parcial como completo.');
  if(v.curriculumMode==='none')return `\n# ${isEn?'APPLICATION AND QUALITY CONTROL':'APLICACIÓN Y CONTROL DE CALIDAD'}\n${[rules[0],rules[6],rules[7],rules[10],rules[11],rules[12]].map(rule=>`- ${rule}`).join('\n')}\n`;
  return `\n# ${isEn?'CURRICULUM SELECTION AND QUALITY CONTROL':'SELECCIÓN CURRICULAR Y CONTROL DE CALIDAD'}\n${rules.map(rule=>`- ${rule}`).join('\n')}\n`;
}
function primaryMathAlignmentPrompt(selected,isEn){
  if(!selected||selected.subject!==selected.data.subjects.mates)return '';
  const links=window.PRIMARY_MATH_ALIGNMENT?.criteriaByGrade[selected.grade];
  if(!links)return '';
  return `\n## ${isEn?'Criterion–knowledge links transcribed from the 2023 official table':'Relaciones criterio–saber transcritas de la tabla oficial de 2023'}\n${selected.criteria.map(item=>{const entry=links[item.code];return `- ${item.code}: ${entry?.sabers.length?entry.sabers.join(', '):(isEn?'Link not extracted; pending verification':'Relación no extraída; pendiente de contraste')}${entry?` (PDF ${entry.pages.join(', ')})`:''}`}).join('\n')}\n`;
}
function infantMapPolicy(selected,isEn){
  if(!selected)return '';
  return `\n# ${isEn?'EARLY CHILDHOOD ASSESSMENT APPROACH':'ENFOQUE DE EVALUACIÓN EN INFANTIL'}\n- ${isEn?'Frame every suggestion as a brief play-based, routine-based, exploratory or interaction-based situation appropriate to the selected cycle. Do not turn the curriculum map into worksheets, written tests or decontextualised performances.':'Formula cada propuesta como una situación breve de juego, rutina, exploración o interacción adecuada al ciclo seleccionado. No conviertas el mapa curricular en fichas, pruebas escritas ni actuaciones descontextualizadas.'}\n- ${isEn?'Describe what the teacher can observe and document over repeated natural situations. Use records such as anecdotal notes, observation scales, learning traces or portfolios only when suitable; one isolated response must not be treated as definitive attainment.':'Describe qué puede observar y documentar el docente en situaciones naturales repetidas. Utiliza registros anecdóticos, escalas de observación, huellas de aprendizaje o portafolios solo cuando sean adecuados; una respuesta aislada no acredita por sí sola la consecución definitiva.'}\n- ${isEn?'Respect individual developmental rhythms and multiple forms of communication, participation and expression. Do not diagnose, rank children or convert developmental observations into fixed labels.':'Respeta los ritmos individuales de desarrollo y las distintas formas de comunicación, participación y expresión. No diagnostiques, clasifiques al alumnado ni conviertas observaciones evolutivas en etiquetas fijas.'}\n- ${isEn?'For each proposed activity, preserve the criterion’s relational, emotional, motor, autonomy and adult-mediation conditions. Individual observable evidence means traceable observation of each child within the natural activity, not necessarily an individual task.':'En cada actividad propuesta conserva las condiciones relacionales, emocionales, motrices, de autonomía y de mediación adulta del criterio. Evidencia individual observable significa observación atribuible a cada niño o niña dentro de la actividad natural, no necesariamente una tarea individual.'}\n`;
}
const generatePromptBeforeBetaAudit=generatePrompt;
generatePrompt=function(){
  generatePromptBeforeBetaAudit();const v=values(),isEn=v.materialLanguage==='English',complete=['annual','coursePack','curriculumMap'].includes(v.resourceId);
  let p=$('#promptOutput').value;
  p=p.replace('generator_version: beta-0.9','generator_version: beta-0.9.9');
  if(v.resourceId==='curriculumMap'){
    p=p.replace(/\n# (CRITERIOS DE CALIDAD|QUALITY REQUIREMENTS)\n[\s\S]*$/,isEn?`\n# QUALITY REQUIREMENTS\n- Preserve every supplied code and the meaning of every required action. Keep official text, summaries and proposals separate. Do not invent missing source content.\n${line('Additional requirements',v.quality)}\n# EXPECTED OUTPUT\n- Use the selected map format and wording option; keep entries concise without reducing coverage.\n- Deliver the finished map, followed by separate coverage, activity-alignment and normative-currency statuses.\n- Tone: ${v.tone||'clear and professional'}\n`:`\n# CRITERIOS DE CALIDAD\n- Conserva todos los códigos aportados y el sentido de cada acción exigida. Separa texto oficial, resúmenes y propuestas. No inventes contenidos ausentes de la fuente.\n${line('Condiciones adicionales',v.quality)}\n# SALIDA ESPERADA\n- Utiliza el formato y la opción de redacción elegidos; mantén entradas concisas sin reducir la cobertura.\n- Entrega el mapa terminado y cierra con estados separados de cobertura, alineación de actividades y vigencia normativa.\n- Tono: ${v.tone||'claro y profesional'}\n`);
    p=p.replace('resume cada elemento con claridad sin alterar su sentido','aplica la opción elegida de redacción oficial o resumen sin alterar el sentido de cada elemento').replace('summarise each item clearly without changing its meaning','apply the selected official-wording or summary option without changing each item’s meaning');
  }
  p=p.replace(`curriculum_mode: ${v.curriculumMode}`,`curriculum_mode: ${v.curriculumMode==='verified'?'embedded_or_linked':v.curriculumMode}\ncurriculum_detail: ${v.curriculumMode==='verified'?curriculumDetailMode(v):'not_applicable'}\ncurriculum_currency: ${v.curriculumMode==='verified'?'pending_consolidated_review':'not_claimed'}`);
  if(!complete){
    p=p.replaceAll('Conserva códigos y sentido; no inventes, fusiones ni omitas elementos.','Conserva códigos y sentido de los elementos seleccionados; no inventes ni fusiones elementos.');
    p=p.replaceAll('Conserva códigos y sentido; no traduzcas la redacción oficial ni inventes, fusiones u omitas elementos.','Conserva códigos y sentido de los elementos seleccionados; no traduzcas la redacción oficial ni inventes o fusiones elementos.');
    p=p.replaceAll('Preserve codes and meaning; do not invent, merge or omit items.','Preserve codes and meaning of selected items; do not invent or merge items.');
    p=p.replaceAll('Preserve codes and meaning; do not translate official wording or invent, merge or omit items.','Preserve codes and meaning of selected items; do not translate official wording or invent or merge items.');
    p=p.replace('Usa esa transcripción y conserva todos sus códigos.','Selecciona los elementos pertinentes de esa transcripción y conserva sus códigos.');
    p=p.replace('Use that transcription and preserve every code.','Select relevant elements from that transcription and preserve their codes.');
  }
  const primary=primaryCurriculumSelection(),infant=infantCurriculumSelection();
  if(v.resourceId==='curriculumMap'&&v.curriculumMode==='verified'&&primary){
    const entries=v.mapCourses==='stage'?Object.values(primary.subject.cycles).flatMap(cycleData=>Object.entries(cycleData.criteriaByGrade).map(([grade,criteria])=>({grade,criteria,cycleData}))):[primary];
    const inventory=`\n# ${isEn?'EXPECTED MAP COVERAGE':'COBERTURA ESPERADA DEL MAPA'}\n${entries.map(entry=>`- ${entry.grade}.º de Primaria: ${entry.cycleData.competencies.length} ${isEn?'competencies':'competencias'}; ${entry.criteria.length} ${isEn?'assessment criteria':'criterios de evaluación'}. ${isEn?'Expected criterion codes':'Códigos de criterios esperados'}: ${entry.criteria.map(item=>item.code).join(', ')}.`).join('\n')}\n`;
    p=p.replace(/\n# (ENCARGO|TASK)\n/,`${inventory}\n# $1\n`);
  }
  if(v.resourceId==='curriculumMap'&&v.curriculumMode==='verified'&&infant){
    const entries=v.mapCourses==='stage'?Object.entries(infant.subject.cycles).map(([cycle,cycleData])=>({cycle,cycleData})):[infant];
    const inventory=`\n# ${isEn?'EXPECTED MAP COVERAGE':'COBERTURA ESPERADA DEL MAPA'}\n${entries.map(entry=>`- ${entry.cycle==='1'?(isEn?'First cycle (0–3 years)':'Primer ciclo (0–3 años)'):(isEn?'Second cycle (3–6 years)':'Segundo ciclo (3–6 años)')}: ${entry.cycleData.competencies.length} ${isEn?'competencies':'competencias'}; ${entry.cycleData.criteria.length} ${isEn?'assessment criteria':'criterios de evaluación'}. ${isEn?'Expected criterion codes':'Códigos de criterios esperados'}: ${entry.cycleData.criteria.map(item=>item.code).join(', ')}.`).join('\n')}\n`;
    p=p.replace(/\n# (ENCARGO|TASK)\n/,`${inventory}\n# $1\n`);
  }
  const links=v.curriculumMode==='verified'?(v.resourceId==='curriculumMap'&&v.mapCourses==='stage'&&primary?Object.values(primary.subject.cycles).flatMap(cycleData=>Object.entries(cycleData.criteriaByGrade).map(([grade,criteria])=>`\n### ${grade}.º de Primaria\n${primaryMathAlignmentPrompt({...primary,grade,criteria},isEn)}`)).join(''):primaryMathAlignmentPrompt(primary,isEn)):'';
  p=p.replace(/\n# (ENCARGO|TASK)\n/,`${curriculumDetailPolicy(v,isEn)}${links}${v.resourceId==='curriculumMap'?infantMapPolicy(infant,isEn):''}${curriculumExecutionPolicy(v,isEn)}\n# $1\n`);
  $('#promptOutput').value=p;$('#promptMeta').textContent=`${p.split(/\s+/).length} ${state.lang?'words':'palabras'} · ${v.ai||'ChatGPT / Codex'}`;
  if(v.curriculumMode==='verified')$('#reviewNotes').innerHTML=`<div class="review-note">⚖️ ${state.lang?'Built-in source transcription; later amendments are not certified as integrated. Review the selected elements and final resource.':'Transcripción de la fuente incorporada; no se certifica la integración de modificaciones posteriores. Revisa la selección y el recurso final.'}</div>`;
};
